import { useNavigate } from "react-router-dom";
import React, { useState, useEffect, useContext } from "react";
import { AuthContext } from "../context/authContext";
import api from "../services/api";
import { API_ENDPOINTS } from "../services/apiEndpoints";
import WallForm from "../components/walls/wallForm";
import TweetForm from "../components/walls/tweetForm";
import TweetList from "../components/walls/tweetList";

const Dashboard = () => {
    const navigate = useNavigate();
    const logoUrl = "/path-to-logo.png"; // Replace with actual logo URL or fetch from user profile

    const handleLogout = () => {
        // Logout logic here
        navigate("/login");
    };

    return (
        <div className="p-6">
            {/* Updated Header */}
            <div className="flex justify-between items-center mb-6">
                <div className="flex items-center">
                    <img
                        src={logoUrl}
                        alt="Logo"
                        className="w-10 h-10 mr-2 rounded-full"
                    />
                    <h2 className="text-2xl font-bold">Abhi's Wall</h2>
                </div>
                <div className="space-x-4">
                    <button
                        onClick={() => navigate("/create-wall")}
                        className="bg-green-500 text-white px-4 py-2 rounded hover:bg-green-600"
                    >
                        Create Wall
                    </button>
                    <button
                        onClick={() => navigate("/profile")}
                        className="bg-green-500 text-white px-4 py-2 rounded hover:bg-green-600"
                    >
                        Profile
                    </button>
                    <button
                        onClick={handleLogout}
                        className="bg-red-500 text-white px-4 py-2 rounded hover:bg-red-600"
                    >
                        Logout
                    </button>
                </div>
            </div>
            <WallForm onWallCreated={handleWallCreated} />
            <div className="mt-6">
                <h3 className="text-xl font-semibold mb-4">Your Walls</h3>
                {walls.length === 0 ? (
                    <p>No walls created yet.</p>
                ) : (
                    <ul className="space-y-4">
                        {walls.map((wall) => (
                            <li
                                key={wall.id}
                                className="p-4 bg-gray-100 rounded-lg shadow"
                            >
                                <div className="flex items-center mb-2">
                                    <img
                                        src={wall?.logo || "/placeholder.jpg"}
                                        alt={wall.title}
                                        className="w-10 h-10 rounded-full mr-3"
                                    />
                                    <div>
                                        <p className="font-semibold text-gray-800">
                                            {wall.title}
                                        </p>
                                        <p>{wall.description}</p>
                                    </div>
                                </div>
                                <p>Public: {wall.is_public ? "Yes" : "No"}</p>
                                {/* {wall.logo && <img src={wall.logo} />}   */}
                                <div className="flex space-x-4 mt-2">
                                    <button
                                        onClick={() => setSelectedWall(wall)}
                                        className="text-blue-500 hover:underline"
                                    >
                                        Manage Tweets
                                    </button>
                                    <button
                                        onClick={() =>
                                            handleGenerateSharableLink(wall.id)
                                        }
                                        className="text-blue-500 hover:underline"
                                    >
                                        Get Sharable Link
                                    </button>
                                    <button
                                        onClick={() =>
                                            handleDeleteWall(wall.id)
                                        }
                                        className="text-red-500 hover:underline"
                                    >
                                        Delete
                                    </button>
                                </div>
                                {sharableLink && (
                                    <p className="mt-2">
                                        Sharable Link:{" "}
                                        <a
                                            href={sharableLink}
                                            className="text-blue-500 hover:underline"
                                        >
                                            {sharableLink}
                                        </a>
                                    </p>
                                )}
                            </li>
                        ))}
                    </ul>
                )}
            </div>
        </div>
    );
};

export default Dashboard;
